// ActionBar — Gtk.ActionBar
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles actionbar with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ActionBarProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.ActionBar */
  revealed?: boolean
}

export function ActionBar({ className, children }: ActionBarProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
